"""Author PRE_A1-U17 only; preserve previous sessions and lexical meanings."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/PRE_A1.plan.json').read_text())['level']
plan=level['units'][16]
W={}
for source in [OUT/f'PRE_A1-U{n:02}.v1.json' for n in range(16,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='PRE_A1.U17.UNDERSTAND';A='PRE_A1.U17.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='PRE_A1',unit_id=plan['id'],description=d,duration_minutes=6,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — французский с нуля',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def phrase_pairs(s,gs,rows,g,b):
 vs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in ws)); avs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in av))
 t=base(s,'vocabulary',gs,vs,avs,'Соедините реплику или выражение с его смыслом.',ru('Используйте каждую карточку один раз.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**fr(f,p)) for i,(f,p,r,ws,av) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(f,p,r,ws,av) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=av) for i,(f,p,r,ws,av) in enumerate(rows)])
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
addword('ici','fr:ici:here-location','ici','здесь','иси́',ex('Le livre est ici.','Книга здесь.','лё ливр э тиси́'),1,[rev('ici-meaning',fr('Ici','иси́'),['Там, в другой указанной точке','Здесь','Под предметом'],1,'В нашем образце слово означает здесь.','Нужно значение здесь; другая точка и положение под предметом обозначаются иначе.'),rev('ici-use',ru('Нужно сообщить «Книга здесь». Какую реплику выбрать?'),[fr('Le livre est là.','лё ливр э ля́'),fr('Le stylo est ici.','лё стило э тиси́'),fr('Le livre est ici.','лё ливр э тиси́')],2,'Названа книга и метка здесь.','Нужно сохранить книгу и метку здесь; другое место или другой предмет меняет условие.')])
addword('la-lieu','fr:la:there-location','là','там (другая указанная точка в наших сценах)','ля́',ex('Le stylo est là.','Ручка там.','лё стило э ля́'),1,[rev('la-lieu-meaning',fr('Là','ля́'),['Там — в другой указанной точке нашей сцены','Здесь — в отмеченной ближней зоне','Под предметом'],0,'В этой учебной сцене выбрано значение там.','Здесь нужно там, в другой указанной точке; не заменяйте его меткой здесь или положением под предметом.'),rev('la-lieu-use',ru('В нашей сцене ручка там, в отдельно указанной точке. Какую реплику выбрать?'),[fr('Le livre est là.','лё ливр э ля́'),fr('Le stylo est là.','лё стило э ля́'),fr('Le stylo est ici.','лё стило э тиси́')],1,'Названа ручка и метка там.','Нужно сохранить ручку и метку там; книга и метка здесь меняют условие.')])
addword('sur','fr:sur:on-surface','sur','на (на поверхности указанного предмета)','сюр',ex('Le livre est sur la chaise.','Книга на стуле.','лё ливр э сюр ла шэ́з'),2,[rev('sur-meaning',fr('Sur','сюр'),['Под','Внутри','На поверхности'],2,'Слово обозначает положение на поверхности.','Нужно значение на поверхности, а не под предметом или внутри него.'),rev('sur-use',ru('Книга находится на стуле. Какую реплику выбрать?'),[fr('Le livre est sur la chaise.','лё ливр э сюр ла шэ́з'),fr('Le livre est sous la chaise.','лё ливр э су ла шэ́з'),fr('Le livre est sur la table.','лё ливр э сюр ла та́бль')],0,'Книга находится на поверхности стула.','Нужны положение на и стул; под стулом или на столе — другое расположение.')])
addword('sous','fr:sous:under','sous','под (указанным предметом)','су',ex('Le stylo est sous la table.','Ручка под столом.','лё стило э су ла та́бль'),2,[rev('sous-meaning',fr('Sous','су'),['Под','На поверхности','Здесь'],0,'Слово обозначает положение под предметом.','Нужно значение под; поверхность и метка здесь означают другое.'),rev('sous-use',ru('Нужно сообщить «Ручка под столом». Какую реплику выбрать?'),[fr('Le stylo est sur la table.','лё стило э сюр ла та́бль'),fr('Le stylo est sous la table.','лё стило э су ла та́бль'),fr('Le livre est sous la table.','лё ливр э су ла та́бль')],1,'Ручка расположена под столом.','Сохраните ручку и положение под столом; поверхность стола или книга меняют условие.')])
addword('dans','fr:dans:inside','dans','в (внутри указанного предмета)','да́(н)',ex('Le stylo est dans la boîte.','Ручка в коробке.','лё стило э да(н) ла буа́т'),3,[rev('dans-meaning',fr('Dans','да́(н)'),['Рядом с','Внутри','Под'],1,'Здесь слово обозначает положение внутри.','Нужно внутри; рядом и под предметом — другие отношения.'),rev('dans-use',ru('Ручка находится внутри коробки. Какую реплику выбрать?'),[fr('Le stylo est sous la boîte.','лё стило э су ла буа́т'),fr('Le stylo est à côté de la boîte.','лё стило э та котэ дё ла буа́т'),fr('Le stylo est dans la boîte.','лё стило э да(н) ла буа́т')],2,'Ручка находится внутри коробки.','Нужно положение внутри; под коробкой и рядом с ней не сохраняют условие.')])
addword('boite','fr:boite:box','une boîte','коробка','юн буа́т',ex('Le stylo est dans la boîte.','Ручка в коробке.','лё стило э да(н) ла буа́т'),3,[rev('boite-meaning',fr('Une boîte','юн буа́т'),['Сумка','Стол','Коробка'],2,'Названа коробка.','Правильное значение — коробка; сумка и стол обозначают другие предметы.'),rev('boite-use',ru('Какое название обозначает коробку, в которую помещена ручка?'),[fr('Une boîte','юн буа́т'),fr('Un sac','э(н) са́к'),fr('Une table','юн та́бль')],0,'Выбрано название коробки.','Нужна коробка; сумка и стол не соответствуют условию.')])
addword('a-cote-de','fr:a-cote-de:next-to','à côté de','рядом с (указанным предметом)','а котэ́ дё',ex('Le livre est à côté de la boîte.','Книга рядом с коробкой.','лё ливр э та котэ дё ла буа́т'),3,[rev('a-cote-de-meaning',fr('À côté de','а котэ́ дё'),['Рядом с','Внутри','Под'],0,'Выражение обозначает положение рядом с ориентиром.','Нужно рядом с; внутри и под — другие пространственные отношения.'),rev('a-cote-de-use',ru('Нужно сообщить «Книга рядом с коробкой». Какую реплику выбрать?'),[fr('Le livre est dans la boîte.','лё ливр э да(н) ла буа́т'),fr('Le livre est à côté de la boîte.','лё ливр э та котэ дё ла буа́т'),fr('Le livre est sous la boîte.','лё ливр э су ла буа́т')],1,'Книга расположена рядом с коробкой.','Нужно рядом; внутри коробки и под ней — другое расположение.')])
addword('a-gauche-de','fr:a-gauche-de:left-of','à gauche de','слева от (указанного ориентира)','а го́ш дё',ex('Le stylo est à gauche de la table.','Ручка слева от стола.','лё стило э та гош дё ла та́бль'),4,[rev('a-gauche-de-meaning',fr('À gauche de','а го́ш дё'),['Справа от','Слева от','Внутри'],1,'Выражение обозначает положение слева от ориентира.','Нужно слева от; справа и внутри обозначают другое.'),rev('a-gauche-de-use',ru('Строка дана слева направо для читающего: ручка — стол — книга. Как сообщить положение ручки относительно стола?'),[fr('Le stylo est à droite de la table.','лё стило э та друат дё ла та́бль'),fr('Le livre est à gauche de la table.','лё ливр э та гош дё ла та́бль'),fr('Le stylo est à gauche de la table.','лё стило э та гош дё ла та́бль')],2,'В заданной строке ручка слева от стола.','Нужны ручка и левая сторона относительно стола; не меняйте предмет или сторону.')])
addword('a-droite-de','fr:a-droite-de:right-of','à droite de','справа от (указанного ориентира)','а друа́т дё',ex('Le livre est à droite de la table.','Книга справа от стола.','лё ливр э та друат дё ла та́бль'),4,[rev('a-droite-de-meaning',fr('À droite de','а друа́т дё'),['Внутри','Слева от','Справа от'],2,'Выражение обозначает положение справа от ориентира.','Нужно справа от; слева и внутри обозначают другое.'),rev('a-droite-de-use',ru('Строка дана слева направо для читающего: книга — стул — ручка. Как сообщить положение ручки относительно стула?'),[fr('Le stylo est à droite de la chaise.','лё стило э та друат дё ла шэ́з'),fr('Le stylo est à gauche de la chaise.','лё стило э та гош дё ла шэ́з'),fr('Le livre est à droite de la chaise.','лё ливр э та друат дё ла шэ́з')],0,'В заданной строке ручка справа от стула.','Нужны ручка и правая сторона относительно стула; другое направление или книга не соответствуют строке.')])

def cards(ids):return [wc(x) for x in ids]
s=start(1,'Различайте здесь и там в коротких сообщениях о книге и ручке. Повторите вопрос о расположении знакомого места.',['ici','la-lieu','livre','stylo','cafe-lieu','cest-ou'])
choose(s,'reading',['PRE_A1.U16.APPLY'],['cafe-lieu','cest-ou'],['cest-ou'],'Что спрашивает человек знакомой репликой?',fr('Le café, c’est où ?','лё кафэ, сэ у́?'),['Когда встреча','Где находится кафе','Какая погода'],1,'Это вопрос о расположении кафе.','Нужен вопрос где кафе; время встречи и погода имеют другие вопросительные образцы.')
intro(s,2,'Ici — «здесь». В наших сценах là означает «там», в другой указанной точке. Не угадывайте точку по голосу или жесту: используйте слово из реплики и условие. Новые образцы о вещи: Le livre est ici. — «Книга здесь», Le stylo est là. — «Ручка там». Показанное est соединяет название вещи и её положение. Формы названий Le livre и Le stylo запоминаем в этих образцах.',['ici','la-lieu'],[('Ici','иси́'),('là','ля́'),('Le livre est ici.','лё ливр э тиси́'),('Le stylo est là.','лё стило э ля́'),('est','э'),('Le livre','лё ли́вр'),('Le stylo','лё стило́')],('Le livre est ici. Le stylo est là.','лё ливр э тиси́. лё стило э ля́.'))
phrase_pairs(s,[U],[('Le livre est ici.','лё ливр э тиси́.','Книга здесь.',['livre','ici'],['ici']),('Le livre est là.','лё ливр э ля́.','Книга там.',['livre','la-lieu'],['la-lieu']),('Le stylo est ici.','лё стило э тиси́.','Ручка здесь.',['stylo','ici'],['ici'])],'Вы сохранили предмет и метку его положения.','Здесь и там различаются по слову; название книги и ручки тоже нужно сохранить.')
listen(s,[U],['livre','stylo','ici','la-lieu'],['ici'],'Какое сообщение о книге прозвучало?','Le livre est ici.','лё ливр э тиси́.',['Книга там','Ручка здесь','Книга здесь'],2,'Книга здесь.','Нужно сохранить книгу и метку здесь; другая точка или ручка не соответствуют фразе.')
choose(s,'vocabulary',[U],['stylo','livre','la-lieu','ici'],['la-lieu'],'В нашей сцене нужно сообщить «Ручка там». Что выбрать?',ru('Сохраните предмет и метку из условия.'),[fr('Le stylo est ici.','лё стило э тиси́.'),fr('Le stylo est là.','лё стило э ля́.'),fr('Le livre est là.','лё ливр э ля́.')],1,'Выбрана ручка в другой указанной точке — там.','Нужны ручка и там; метка здесь и книга меняют условие.')
choose(s,'reading',[U],['livre','stylo','ici','la-lieu'],['ici','livre'],'Какая вещь находится здесь по двум репликам?',fr('Le livre est ici. Le stylo est là.','лё ливр э тиси́. лё стило э ля́.'),['Книга','Ручка','Обе вещи'],0,'Здесь находится книга, а ручка обозначена меткой там.','Сопоставьте метку с вещью в той же реплике: здесь — книга.')
fill(s,[U],['stylo','ici','la-lieu'],['ici'],'Дополните «Ручка здесь».','Le stylo est ','лё стило э́','','',cards(['la-lieu','ici']),1,'Le stylo est ici','лё стило э тиси́','Выбрана метка здесь.','Нужно здесь; другая метка указывает там в нашей сцене.')
order(s,[U],['livre','la-lieu'],[],'Соберите «Книга там». Начните с названия вещи.',[('Le livre','лё ли́вр'),('est','э'),('là.','ля́')],'Le livre est là.','лё ливр э ля́.','Получился показанный образец положения книги.','Сначала поставьте название книги, затем связующую форму и метку там.')
page(s,[('Две метки в учебной сцене',['Здесь и там различаются по явно названной метке. В наших сценах там указывает другую обозначенную точку; не нужно угадывать её по синтетическому голосу или воображаемому жесту.'],[W['ici']['example'],W['la-lieu']['example']]),('Короткая фраза о вещи',['В изученном образце сначала назван предмет, затем показанная связующая форма и его положение. Здесь не требуется полная таблица глагола.'],[ex('Le livre est là.','Книга там.','лё ливр э ля́')]),('Читаем обе реплики',['Если названы две вещи, соотнесите каждую со своей меткой. Местоположение одной вещи не переносится автоматически на другую.'],[ex('Le livre est ici. Le stylo est là.','Книга здесь. Ручка там.','лё ливр э тиси́. лё стило э ля́')])])
